"""Step 48D part D: NOTICE is generated by `python tasks.py notices` from the installed package metadata (name, version
and the license exactly as the metadata declares it), under the project's own license text. No license text is written
by hand, and a dependency named in a requirements file that is missing from NOTICE fails this test."""

from __future__ import annotations

import re
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

import tasks  # noqa: E402

ROOT = Path(__file__).resolve().parents[2]
NOTICE = ROOT / "NOTICE"


def _pins() -> dict[str, str]:
    pins: dict[str, str] = {}
    for name in ("requirements.txt", "requirements-dev.txt"):
        for line in (ROOT / name).read_text(encoding="utf-8").splitlines():
            line = line.split("#")[0].split(";")[0].strip()
            if line:
                package, _, version = line.partition("==")
                pins[re.sub(r"[-_.]+", "-", package).lower()] = version.strip()
    return pins


def _notice_rows() -> dict[str, str]:
    rows = {}
    for line in NOTICE.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^(\S+) (\S+) \| ", line)
        if m:
            rows[re.sub(r"[-_.]+", "-", m.group(1)).lower()] = m.group(2)
    return rows


# -- the committed file --------------------------------------------------------------------------------------------
def test_notice_exists_and_starts_with_the_projects_own_license_text_unchanged():
    assert NOTICE.exists()
    license_text = (ROOT / "LICENSE").read_text(encoding="utf-8").strip()
    assert NOTICE.read_text(encoding="utf-8").startswith(license_text)


def test_every_dependency_named_in_the_requirements_files_is_in_notice_with_its_pinned_version():
    rows = _notice_rows()
    pins = _pins()
    assert len(pins) >= 40
    assert sorted(set(pins) - set(rows)) == []
    assert {n: v for n, v in pins.items() if rows[n] != v} == {}


def test_notice_is_lf_only_and_says_how_it_was_made():
    raw = NOTICE.read_bytes()
    assert b"\r" not in raw
    assert b"python tasks.py notices" in raw


def test_the_bundled_font_license_is_pointed_to_not_retyped():
    text = NOTICE.read_text(encoding="utf-8")
    assert "ui/fonts/OFL.txt" in text and (ROOT / "ui/fonts/OFL.txt").exists()
    assert "SIL Open Font License" not in text  # the text lives in its own file


# -- the generator, with made-up metadata ---------------------------------------------------------------------------
def meta(version="1.0", expression=None, license_field=None, classifiers=()):
    return {"version": version, "expression": expression, "license": license_field, "classifiers": list(classifiers)}


def build(lookup, requirement_lines=("alpha==1.0",)):
    return tasks.build_notice(
        "MIT License\n\nCopyright (c) 2026 Someone\n", {"requirements.txt": list(requirement_lines)}, lookup
    )


def test_the_license_expression_is_used_as_declared():
    out = build(
        {"alpha": meta(expression="Apache-2.0 OR BSD-3-Clause", license_field="ignored?", classifiers=["License :: X"])}
    )
    assert "alpha 1.0 | License-Expression: Apache-2.0 OR BSD-3-Clause" in out


def test_a_short_license_field_and_the_classifiers_are_shown_as_declared():
    out = build({"alpha": meta(license_field="Dual License", classifiers=["License :: OSI Approved :: BSD License"])})
    assert "License: Dual License" in out and "Classifier: License :: OSI Approved :: BSD License" in out


def test_a_long_license_field_is_not_copied_and_is_said_so():
    out = build({"alpha": meta(license_field="x" * 500)})
    assert "x" * 50 not in out and "License field holds a full text" in out


def test_a_package_that_declares_nothing_is_not_given_a_license():
    out = build({"alpha": meta()})
    assert "alpha 1.0 | no license declared in the package metadata" in out


def test_the_version_comes_from_the_installed_package_and_a_mismatch_with_the_pin_stops():
    with pytest.raises(tasks.NoticeError, match="alpha"):
        build({"alpha": meta(version="2.0")})


def test_a_missing_package_stops_unless_a_platform_marker_excludes_it():
    with pytest.raises(tasks.NoticeError, match="alpha"):
        build({})
    out = build({}, ['alpha==1.0; sys_platform == "nonexistent"'])
    assert "alpha 1.0 | not installed on this platform" in out


def test_the_project_license_comes_first_and_the_rows_are_sorted():
    out = build(
        {"beta": meta(expression="MIT", version="2"), "alpha": meta(expression="MIT")}, ["beta==2", "alpha==1.0"]
    )
    assert out.startswith("MIT License")
    assert out.index("alpha 1.0 |") < out.index("beta 2 |")


def test_notices_refuses_arguments(capsys):
    assert tasks.notices(["--force"]) == 2
